solution.solution.cpp:
#include <algorithm>
#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

class Level
{
public:
    Level(int width, int height, char fill)
        : m_w{ width }, m_h{ height }, m_tiles(static_cast<std::size_t>(width) * static_cast<std::size_t>(height), fill) {}

    int width() const { return m_w; }
    int height() const { return m_h; }
    char at(int x, int y) const { return inside(x, y) ? m_tiles[index(x, y)] : ' '; }

    void strokeBegin() { m_stroke.clear(); m_inStroke = true; }

    void strokePaint(int x, int y, char tile)
    {
        if (!m_inStroke || !inside(x, y)) return;
        const std::size_t i{ index(x, y) };
        if (!m_stroke.count(i)) m_stroke[i] = { m_tiles[i], tile };
        else m_stroke[i].second = tile;
        m_tiles[i] = tile;
    }

    void strokeEnd()
    {
        if (!m_inStroke) return;
        m_inStroke = false;
        Step s;
        for (const auto& [i, change] : m_stroke) if (change.first != change.second) s.push_back({ i, change.first, change.second });
        m_stroke.clear();
        record(std::move(s));
    }

    void rectangle(int x0, int y0, int x1, int y1, char tile)
    {
        if (x0 > x1) std::swap(x0, x1);
        if (y0 > y1) std::swap(y0, y1);
        x0 = std::max(x0, 0); y0 = std::max(y0, 0);
        x1 = std::min(x1, m_w - 1); y1 = std::min(y1, m_h - 1);
        Step s;
        for (int y{ y0 }; y <= y1; ++y)
            for (int x{ x0 }; x <= x1; ++x)
            {
                const std::size_t i{ index(x, y) };
                if (m_tiles[i] != tile) { s.push_back({ i, m_tiles[i], tile }); m_tiles[i] = tile; }
            }
        record(std::move(s));
    }

    void floodFill(int x, int y, char tile)
    {
        if (!inside(x, y)) return;
        const char from{ m_tiles[index(x, y)] };
        if (from == tile) return;
        Step s;
        std::vector<std::pair<int, int>> todo{ { x, y } };
        while (!todo.empty())
        {
            const auto [cx, cy] { todo.back() };
            todo.pop_back();
            if (!inside(cx, cy)) continue;
            const std::size_t i{ index(cx, cy) };
            if (m_tiles[i] != from) continue;
            m_tiles[i] = tile;
            s.push_back({ i, from, tile });
            todo.push_back({ cx + 1, cy }); todo.push_back({ cx - 1, cy });
            todo.push_back({ cx, cy + 1 }); todo.push_back({ cx, cy - 1 });
        }
        record(std::move(s));
    }

    bool undo()
    {
        if (m_undo.empty()) return false;
        Step s{ std::move(m_undo.back()) };
        m_undo.pop_back();
        for (auto it{ s.rbegin() }; it != s.rend(); ++it) m_tiles[it->index] = it->before;
        m_redo.push_back(std::move(s));
        --m_position;
        return true;
    }

    bool redo()
    {
        if (m_redo.empty()) return false;
        Step s{ std::move(m_redo.back()) };
        m_redo.pop_back();
        for (const auto& c : s) m_tiles[c.index] = c.after;
        m_undo.push_back(std::move(s));
        ++m_position;
        return true;
    }

    bool dirty() const { return m_position != m_saved; }
    void markSaved() { m_saved = m_position; }

    std::string save() const
    {
        std::string out{ "xenon-level 1\nsize " + std::to_string(m_w) + " " + std::to_string(m_h) + "\ntiles\n" };
        for (int y{ 0 }; y < m_h; ++y) out += std::string(m_tiles.begin() + static_cast<std::ptrdiff_t>(y) * m_w, m_tiles.begin() + static_cast<std::ptrdiff_t>(y + 1) * m_w) + "\n";
        return out;
    }

    static bool load(const std::string& text, Level& out)
    {
        std::istringstream in{ text };
        std::vector<std::string> lines;
        for (std::string l; std::getline(in, l);) { if (!l.empty() && l.back() == '\r') l.pop_back(); lines.push_back(l); }
        if (lines.size() < 3 || lines[0] != "xenon-level 1" || lines[2] != "tiles") return false;
        std::istringstream size{ lines[1] };
        std::string word;
        int w{ 0 }, h{ 0 };
        if (!(size >> word >> w >> h) || word != "size" || w < 1 || h < 1 || w > 1000 || h > 1000) return false;
        std::string rest;
        if (size >> rest) return false;
        if (lines.size() != static_cast<std::size_t>(3 + h)) return false;
        Level level{ w, h, ' ' };
        for (int y{ 0 }; y < h; ++y)
        {
            const std::string& row{ lines[static_cast<std::size_t>(3 + y)] };
            if (static_cast<int>(row.size()) != w) return false;
            std::copy(row.begin(), row.end(), level.m_tiles.begin() + static_cast<std::ptrdiff_t>(y) * w);
        }
        out = std::move(level);
        return true;
    }

private:
    struct Change { std::size_t index; char before; char after; };
    using Step = std::vector<Change>;

    bool inside(int x, int y) const { return x >= 0 && y >= 0 && x < m_w && y < m_h; }
    std::size_t index(int x, int y) const { return static_cast<std::size_t>(y) * static_cast<std::size_t>(m_w) + static_cast<std::size_t>(x); }

    void record(Step s)
    {
        if (s.empty()) return;
        if (m_saved > m_position) m_saved = -1000000;
        m_redo.clear();
        m_undo.push_back(std::move(s));
        ++m_position;
    }

    int m_w, m_h;
    std::vector<char> m_tiles;
    std::map<std::size_t, std::pair<char, char>> m_stroke;
    bool m_inStroke{ false };
    std::vector<Step> m_undo, m_redo;
    long m_position{ 0 }, m_saved{ 0 };
};

unitTests:
std::string row(const Level& l, int y) { std::string s; for (int x = 0; x < l.width(); ++x) s += l.at(x, y); return s; }
TEST("a stroke is one step") {
    Level l{ 5, 3, '.' };
    l.strokeBegin(); l.strokePaint(0, 0, '#'); l.strokePaint(1, 0, '#'); l.strokePaint(1, 0, '~'); l.strokePaint(9, 9, '#'); l.strokeEnd();
    CHECK_EQ(row(l, 0), std::string("#~...")); CHECK(l.dirty());
    CHECK(l.undo()); CHECK_EQ(row(l, 0), std::string(".....")); CHECK(!l.undo()); CHECK(!l.dirty());
    CHECK(l.redo()); CHECK_EQ(row(l, 0), std::string("#~..."));
}
TEST("a stroke that changes nothing") { Level l{ 3, 1, '.' }; l.strokeBegin(); l.strokePaint(0, 0, '#'); l.strokePaint(0, 0, '.'); l.strokeEnd(); CHECK(!l.undo()); CHECK(!l.dirty()); }
TEST("rectangle, any corners, clipped") { Level l{ 5, 3, '.' }; l.rectangle(3, 2, 1, 1, '#'); CHECK_EQ(row(l, 1), std::string(".###.")); CHECK_EQ(row(l, 2), std::string(".###.")); l.rectangle(-5, -5, 0, 10, '~'); CHECK_EQ(row(l, 0), std::string("~....")); l.undo(); CHECK_EQ(row(l, 0), std::string(".....")); }
TEST("flood fill") {
    Level l{ 5, 3, '.' }; l.rectangle(2, 0, 2, 2, '#');
    l.floodFill(0, 0, '~'); CHECK_EQ(row(l, 0), std::string("~~#..")); CHECK_EQ(row(l, 2), std::string("~~#.."));
    l.floodFill(0, 0, '~'); l.undo(); CHECK_EQ(row(l, 1), std::string("..#.."));
}
TEST("a big fill is fine") { Level l{ 1000, 1000, '.' }; l.floodFill(500, 500, '#'); CHECK_EQ(l.at(999, 999), '#'); l.undo(); CHECK_EQ(l.at(0, 0), '.'); }
TEST("save and load") {
    Level l{ 4, 2, '.' }; l.rectangle(1, 0, 2, 0, '#');
    CHECK_EQ(l.save(), std::string("xenon-level 1\nsize 4 2\ntiles\n.##.\n....\n"));
    Level back{ 1, 1, '?' }; CHECK(Level::load("xenon-level 1\r\nsize 4 2\r\ntiles\r\n.##.\r\n....\r\n", back));
    CHECK_EQ(back.width(), 4); CHECK_EQ(row(back, 0), std::string(".##.")); CHECK(!back.dirty()); CHECK(!back.undo());
}
TEST("bad files") {
    Level keep{ 2, 1, 'k' };
    CHECK(!Level::load("xenon-level 2\nsize 1 1\ntiles\n.\n", keep)); CHECK(!Level::load("xenon-level 1\nsize 2 1\ntiles\n.\n", keep));
    CHECK(!Level::load("xenon-level 1\nsize 1 2\ntiles\n.\n", keep)); CHECK(!Level::load("xenon-level 1\nsize 0 1\ntiles\n", keep)); CHECK(!Level::load("", keep));
    CHECK_EQ(keep.width(), 2); CHECK_EQ(keep.at(0, 0), 'k');
}
TEST("dirty after save and undo") { Level l{ 3, 1, '.' }; l.rectangle(0, 0, 0, 0, '#'); l.markSaved(); CHECK(!l.dirty()); l.rectangle(1, 0, 1, 0, '#'); CHECK(l.dirty()); l.undo(); CHECK(!l.dirty()); }

